package com.aurasound.next;
import android.app.Activity;import android.os.Bundle;import android.os.Build;import android.Manifest;import android.content.pm.PackageManager;import android.content.Intent;import android.content.IntentFilter;import android.net.Uri;import android.provider.MediaStore;import android.database.Cursor;import android.webkit.*;import android.widget.Toast;import android.media.AudioManager;import android.content.BroadcastReceiver;import android.content.Context;import org.json.JSONArray;import org.json.JSONObject;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public class MainActivity extends Activity{
 private WebView webView;private ValueCallback<Uri[]> fileCallback;private boolean pageReady=false;private final ExecutorService libraryExecutor=Executors.newSingleThreadExecutor();private static final int FILE_PICKER=4102,AUDIO_PERMISSION=4103,NOTIFICATION_PERMISSION=4104,VISUALIZER_PERMISSION=4105;
 private final BroadcastReceiver playbackReceiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){if(webView!=null&&pageReady){byte[] fft=i.getByteArrayExtra("fft");if(fft!=null){StringBuilder a=new StringBuilder("[");for(int n=0;n<fft.length;n++){if(n>0)a.append(",");a.append(fft[n]&255);}a.append("]");String js="window.onNativeVisualizer && window.onNativeVisualizer("+a+")";webView.post(()->webView.evaluateJavascript(js,null));return;}int index=i.getIntExtra("index",-1);boolean playing=i.getBooleanExtra("playing",false);String title=i.getStringExtra("title");String artist=i.getStringExtra("artist");int pos=i.getIntExtra("position",0),dur=i.getIntExtra("duration",0);String js="window.onNativePlaybackState && window.onNativePlaybackState("+index+","+playing+","+JSONObject.quote(title==null?"":title)+","+JSONObject.quote(artist==null?"":artist)+","+pos+","+dur+")";webView.post(()->webView.evaluateJavascript(js,null));}}};
 @Override public void onCreate(Bundle state){super.onCreate(state);setVolumeControlStream(AudioManager.STREAM_MUSIC);getWindow().setStatusBarColor(android.graphics.Color.rgb(3,7,18));getWindow().setNavigationBarColor(android.graphics.Color.rgb(3,7,18));webView=new WebView(this);webView.setBackgroundColor(android.graphics.Color.rgb(3,7,18));WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(true);s.setAllowContentAccess(true);
 webView.addJavascriptInterface(new Object(){
 @JavascriptInterface public String getAudioTracks(){return queryAudioTracks();}
 @JavascriptInterface public void playNative(String queue,int index,boolean autoplay){try{Intent x=new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_SET_QUEUE).putExtra("queue",queue).putExtra("index",index).putExtra("autoplay",autoplay);if(Build.VERSION.SDK_INT>=26)startForegroundService(x);else startService(x);}catch(Exception e){runOnUiThread(()->Toast.makeText(MainActivity.this,"پخش در پس‌زمینه ممکن نیست",Toast.LENGTH_SHORT).show());}}
 @JavascriptInterface public void toggleNative(){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_TOGGLE));}
 @JavascriptInterface public void nextNative(){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_NEXT));}
 @JavascriptInterface public void prevNative(){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_PREVIOUS));}
 @JavascriptInterface public void seekNative(int position){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_SEEK).putExtra("position",position));}
 @JavascriptInterface public void setEqBand(int band,int level){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_EQ_BAND).putExtra("band",band).putExtra("level",level));}
 @JavascriptInterface public void setEqBass(int level){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_EQ_BASS).putExtra("level",level));}
 @JavascriptInterface public void setEqTreble(int level){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_EQ_TREBLE).putExtra("level",level));}
 @JavascriptInterface public void setEqAmp(float level){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_EQ_AMP).putExtra("level",level));}
 @JavascriptInterface public void resetNativeEq(){startService(new Intent(MainActivity.this,PlaybackService.class).setAction(PlaybackService.ACTION_EQ_RESET));}
 @JavascriptInterface public void shareTrack(String title,String uri){runOnUiThread(()->{try{Intent i=new Intent(Intent.ACTION_SEND);i.setType("audio/*");i.putExtra(Intent.EXTRA_STREAM,Uri.parse(uri));i.putExtra(Intent.EXTRA_SUBJECT,title);i.putExtra(Intent.EXTRA_TEXT,title);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"اشتراک‌گذاری آهنگ"));}catch(Exception e){Toast.makeText(MainActivity.this,"اشتراک‌گذاری ممکن نیست",Toast.LENGTH_SHORT).show();}});}
 },"AuraNative");
 webView.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("audio/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,FILE_PICKER);return true;}});
 webView.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){pageReady=true;if(hasPermission()){sendTracks();requestVisualizerPermission();}else requestAudioPermission();requestNotificationPermission();}});setContentView(webView);webView.loadUrl("file:///android_asset/index.html");
 if(Build.VERSION.SDK_INT>=33)registerReceiver(playbackReceiver,new IntentFilter(PlaybackService.ACTION_STATE),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(playbackReceiver,new IntentFilter(PlaybackService.ACTION_STATE));
 }
 private void requestVisualizerPermission(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},VISUALIZER_PERMISSION);}
 private void requestNotificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFICATION_PERMISSION);}
 private boolean hasPermission(){if(Build.VERSION.SDK_INT>=33)return checkSelfPermission(Manifest.permission.READ_MEDIA_AUDIO)==PackageManager.PERMISSION_GRANTED;return Build.VERSION.SDK_INT<23||checkSelfPermission(Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED;}
 private void requestAudioPermission(){if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.READ_MEDIA_AUDIO},AUDIO_PERMISSION);else if(Build.VERSION.SDK_INT>=23)requestPermissions(new String[]{Manifest.permission.READ_EXTERNAL_STORAGE},AUDIO_PERMISSION);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==AUDIO_PERMISSION){if(hasPermission()){sendTracks();requestVisualizerPermission();}else Toast.makeText(this,"برای یافتن آهنگ‌ها، دسترسی موسیقی را از تنظیمات برنامه فعال کنید.",Toast.LENGTH_LONG).show();}else if(r==VISUALIZER_PERMISSION){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED){startService(new Intent(this,PlaybackService.class).setAction(PlaybackService.ACTION_VISUALIZER_REFRESH));}else Toast.makeText(this,"برای نمایش واکنش زنده به صدا، مجوز میکروفون را فعال کنید.",Toast.LENGTH_LONG).show();}}
 private String queryAudioTracks(){JSONArray a=new JSONArray();if(!hasPermission())return a.toString();String[] cols={MediaStore.Audio.Media._ID,MediaStore.Audio.Media.TITLE,MediaStore.Audio.Media.ARTIST,MediaStore.Audio.Media.ALBUM,MediaStore.Audio.Media.SIZE,MediaStore.Audio.Media.DATE_ADDED};try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,cols,MediaStore.Audio.Media.IS_MUSIC+" != 0",null,MediaStore.Audio.Media.TITLE+" COLLATE NOCASE ASC")){if(c!=null)while(c.moveToNext()){JSONObject o=new JSONObject();long id=c.getLong(0);o.put("url",Uri.withAppendedPath(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,String.valueOf(id)).toString());o.put("name",c.getString(1)==null?"بدون نام":c.getString(1));o.put("artist",c.getString(2)==null?"ناشناخته":c.getString(2));o.put("album",c.getString(3)==null?"حافظه دستگاه":c.getString(3));o.put("size",c.getLong(4));o.put("date",c.getLong(5)*1000);a.put(o);}}catch(Exception ignored){}return a.toString();}
 private void sendTracks(){if(webView==null||!pageReady)return;libraryExecutor.execute(()->{String json=queryAudioTracks();runOnUiThread(()->{if(webView!=null&&pageReady)webView.evaluateJavascript("window.loadNativeTracks && window.loadNativeTracks(JSON.parse("+JSONObject.quote(json)+"))",null);});});}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==FILE_PICKER&&fileCallback!=null){Uri[] out=null;if(c==RESULT_OK&&d!=null){if(d.getClipData()!=null){int n=d.getClipData().getItemCount();out=new Uri[n];for(int x=0;x<n;x++)out[x]=d.getClipData().getItemAt(x).getUri();}else if(d.getData()!=null)out=new Uri[]{d.getData()};}fileCallback.onReceiveValue(out);fileCallback=null;}}
 @Override protected void onResume(){super.onResume();if(hasPermission())sendTracks();}
 @Override protected void onDestroy(){try{unregisterReceiver(playbackReceiver);}catch(Exception ignored){}super.onDestroy();}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}
}